// Worker entry: OpenNext handler plus (1) NFT preview PNGs rendered with resvg-wasm and (2) the Workers Cache API for public GET responses.
// (The Cache API only stores entries on a custom domain / route, not on *.workers.dev.)
// @ts-ignore generated by `opennextjs-cloudflare build`
import openNext from './.open-next/worker.js';
import {nftPreviewResponse} from './lib/nft-preview-cf';
import {apiRoute} from './lib/api-route';
// @ts-ignore re-exported Durable Objects, if the OpenNext config enables any
export * from './.open-next/worker.js';

const PREVIEW=/^\/api\/nft\/preview\/v2\/([^/]+)$/;
export default {
 async fetch(request:Request,env:any,ctx:ExecutionContext):Promise<Response>{
  const url=new URL(request.url);
  if(request.method==='GET'){
   const m=PREVIEW.exec(url.pathname);
   if(m)return cached(request,ctx,()=>nftPreviewResponse(decodeURIComponent(m[1]),async()=>new Uint8Array(await (await env.ASSETS.fetch(new Request(url.origin+'/fonts/roboto-mono.ttf'))).arrayBuffer())));
  }
  // The game API is framework-independent (Request -> Response), so it bypasses Next.js/OpenNext. Card images (/api/card/*) still need Next's ImageResponse.
  if((request.method==='GET'||request.method==='POST')&&url.pathname.startsWith('/api/')&&!url.pathname.startsWith('/api/card/')&&!url.pathname.startsWith('/api/nft/preview/')){
   if(request.method==='GET')return cached(request,ctx,()=>apiRoute(request));
   return apiRoute(request);
  }
  if(request.method==='GET'&&url.pathname.startsWith('/api/'))return cached(request,ctx,()=>(openNext as any).fetch(request,env,ctx));
  return (openNext as any).fetch(request,env,ctx);
 },
};
async function cached(request:Request,ctx:ExecutionContext,render:()=>Promise<Response>):Promise<Response>{
 const cache=(caches as any).default as Cache;
 const key=new Request(request.url,{method:'GET'});
 const hit=await cache.match(key);if(hit)return hit;
 const response=await render();
 const cc=response.headers.get('Cache-Control')||'';
 if(response.status===200&&/(s-maxage|max-age)=[1-9]/.test(cc)&&/public/.test(cc)&&!response.headers.has('Set-Cookie')){ctx.waitUntil(cache.put(key,response.clone()));}
 return response;
}
